  ('fb042f60-9f1d-4c80-ac52-ac4ee0cd03fe', 'Analyn', 'B', 29, 'mandaluyong', 'ncr', array['nanny']::text[], '{"nanny": 6}'::jsonb, array['childcare', 'firstaid', 'laundry']::text[], array['toddler']::text[], false, array['tagalog', 'english']::text[], 13000, 'live-out', array['sun']::text[], array['mandaluyong']::text[], '2w', 'Mahilig ako sa mga bata. May first aid training ako at sanay sa toddler routine: tulog, kain, laro.', 'Story time before nap, with funny voices.', null, null, null, '[{"text": "Patient with our twins, and kept a clear daily log.", "who": "Cruz family · Mandaluyong"}]'::jsonb, '[{"years": "2021–2026", "text": "Nanny for twins, Mandaluyong"}, {"years": "2019–2021", "text": "Daycare assistant, Antipolo"}]'::jsonb, 'f', 6, 'Mon–Sat · Can start in 2 weeks', false),
  ('567dacee-469e-43bd-ae88-ecf1593ba032', 'Marites', 'V', 46, 'paranaque', 'ncr', array['housekeeper', 'cook']::text[], '{"housekeeper": 15}'::jsonb, array['cooking', 'laundry']::text[], array[]::text[], false, array['tagalog', 'bisaya']::text[], 14000, 'live-in', array['sun']::text[], array['paranaque']::text[], '1m', '15 taon na sa mga bahay sa Parañaque at Las Piñas. Maayos sa bahay at masarap magluto ng lutong-bahay.', 'Sunday-style kare-kare, any day of the week.', null, null, null, '[{"text": "Ten years with us. Our home ran smoothly because of her.", "who": "Santiago family · Parañaque"}]'::jsonb, '[{"years": "2016–2026", "text": "Housekeeper and cook, BF Homes"}, {"years": "2011–2016", "text": "Housekeeper, Las Piñas"}]'::jsonb, 'f', 15, 'Live-in · Sunday off', false),
  ('96bda845-5899-4a04-af05-726856f6d627', 'Joy', 'C', 24, 'qc', 'ncr', array['allaround']::text[], '{"allaround": 3}'::jsonb, array['laundry', 'cooking', 'petcare']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 10500, 'live-out', array['sat', 'sun']::text[], array['qc']::text[], 'now', 'Masipag at mabilis matuto. Sanay sa general cleaning, laundry, at pag-aalaga ng aso.', 'A freshly folded laundry pile.', null, null, null, '[{"text": "Our two dogs love her, and the house was always tidy.", "who": "Ramos family · QC"}]'::jsonb, '[{"years": "2023–2026", "text": "All-around helper, Teachers Village, QC"}]'::jsonb, 'f', 3, 'Mon–Fri, 8 AM to 5 PM · Available now', false),
  ('ddbf5201-bf48-4f0a-a90c-61b99152ed70', 'Teresita', 'M', 52, 'marikina', 'ncr', array['caregiver']::text[], '{"caregiver": 18}'::jsonb, array['firstaid', 'cooking']::text[], array['elder']::text[], false, array['tagalog', 'ilocano']::text[], 16000, 'live-in', array['sun']::text[], array['marikina']::text[], '1m', 'Caregiver para sa mga lolo at lola sa bahay sa loob ng 18 taon. Marunong sa vital signs, gamot, at therapy exercises.', 'Morning walks with my lola, slow and steady.', null, null, null, '[{"text": "Gentle with my mother, and she kept us updated every day.", "who": "Lopez family · Marikina"}]'::jsonb, '[{"years": "2018–2026", "text": "Caregiver for a lola with dementia, Marikina"}, {"years": "2008–2018", "text": "Home caregiver, Baguio"}]'::jsonb, 'f', 18, 'Live-in · Sunday off', false),
  ('7eed4a85-8b15-4445-ad3d-ba6bf6b052fb', 'Ronaldo', 'F', 41, 'makati', 'ncr', array['driver']::text[], '{"driver": 14}'::jsonb, array['driving']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 18000, 'live-out', array['sun']::text[], array['makati']::text[], '1m', 'Professional driver with 14 years of experience. Alam ko ang Metro Manila routes at maingat ako magmaneho.', 'Getting the kids to school before the first bell.', null, null, null, '[{"text": "Always on time for school runs, and the car is always clean.", "who": "Uy family · Makati"}]'::jsonb, '[{"years": "2017–2026", "text": "Family driver, Makati"}, {"years": "2012–2017", "text": "Company driver, Ortigas"}]'::jsonb, 'm', 14, 'Mon–Sat · Start next month', false),
  ('e44f469b-d56a-431d-a28b-97672a4caf26', 'Charmaine', 'D', 27, 'cebu', 'r7', array['nanny', 'housekeeper']::text[], '{"nanny": 5}'::jsonb, array['childcare', 'laundry', 'tutoring']::text[], array['toddler']::text[], false, array['bisaya', 'tagalog', 'english']::text[], 9500, 'live-in', array['sun']::text[], array['cebu']::text[], '2w', 'Taga-Cebu ko. Kahibalo ko mag-atiman og bata ug motabang sa homework. Patient and organized.', 'Reading practice with flashcards.', null, null, null, '[{"text": "She helped our son with reading every afternoon.", "who": "Go family · Cebu City"}]'::jsonb, '[{"years": "2021–2026", "text": "Nanny, Lahug, Cebu City"}]'::jsonb, 'f', 5, 'Live-in · Sunday off', false),
  ('bf2d0426-ae86-4cc0-a86f-2819fac2bcc7', 'Elvira', 'S', 38, 'davao', 'r11', array['cook', 'housekeeper']::text[], '{"cook": 10}'::jsonb, array['cooking', 'laundry']::text[], array[]::text[], false, array['bisaya', 'tagalog']::text[], 9000, 'live-out', array['sun']::text[], array['davao']::text[], 'now', 'Lutong Davao, Bisaya, at Tagalog. Malinis sa kusina at marunong mag-budget sa palengke.', 'Market runs at dawn for the freshest fish.', null, null, null, '[{"text": "Her tinolang manok is the best we''ve had.", "who": "Dela Paz family · Davao"}]'::jsonb, '[{"years": "2018–2026", "text": "Cook and housekeeper, Lanang, Davao"}]'::jsonb, 'f', 10, 'Mon–Sat, 7 AM to 4 PM', false),
  ('96f7c976-5e01-4e42-a89d-b9722efb1f66', 'Princess', 'A', 22, 'pasig', 'ncr', array['nanny']::text[], '{"nanny": 2}'::jsonb, array['childcare', 'tutoring']::text[], array['toddler']::text[], false, array['tagalog', 'english']::text[], 10000, 'live-out', array['sat', 'sun']::text[], array['pasig']::text[], '2w', 'Graduated in education, now a nanny. I like teaching kids colors, numbers and songs.', 'Singing the alphabet song in three tunes.', null, null, null, '[{"text": "Our daughter learned her ABCs with her.", "who": "Navarro family · Pasig"}]'::jsonb, '[{"years": "2024–2026", "text": "Nanny for a 3-year-old, Kapitolyo"}]'::jsonb, 'f', 2, 'Weekdays, 7 AM to 6 PM', false),
  ('5cb33c17-3672-46e2-aacb-d3d47e7da0b4', 'Lourdes', 'P', 44, 'muntinlupa', 'ncr', array['housekeeper']::text[], '{"housekeeper": 12}'::jsonb, array['laundry', 'cooking', 'petcare']::text[], array[]::text[], false, array['tagalog']::text[], 13500, 'live-in', array['sun']::text[], array['muntinlupa']::text[], '1m', 'Sanay sa malalaking bahay sa Alabang. Maayos sa paglilinis, paglalaba at pagplantsa.', 'Perfectly ironed school uniforms.', null, null, null, '[{"text": "Our home has never been this organized.", "who": "Sy family · Alabang"}]'::jsonb, '[{"years": "2015–2026", "text": "Housekeeper, Ayala Alabang"}, {"years": "2013–2015", "text": "Laundry staff, Muntinlupa"}]'::jsonb, 'f', 12, 'Live-in · Sunday off', false),
  ('7abb990e-f51d-4bfd-ad62-b2eda894f012', 'Jomar', 'T', 33, 'bgc', 'ncr', array['driver', 'allaround']::text[], '{"driver": 8}'::jsonb, array['driving']::text[], array[]::text[], false, array['tagalog', 'english']::text[], 17000, 'live-out', array['sat', 'sun']::text[], array['bgc']::text[], 'now', 'Driver and all-around helper. I can do errands, small repairs and grocery runs.', 'Fixing a squeaky door before anyone notices.', null, null, null, '[{"text": "Reliable with errands and great with small fixes.", "who": "Park family · BGC"}]'::jsonb, '[{"years": "2020–2026", "text": "Driver and errands, BGC"}, {"years": "2018–2020", "text": "Delivery driver, Taguig"}]'::jsonb, 'm', 8, 'Mon–Fri · Available now', false),
  ('9279df39-0826-46f7-a132-5a7b7289a3e9', 'Rowena', 'G', 35, 'sanjuan', 'ncr', array['nanny', 'cook']::text[], '{"nanny": 9}'::jsonb, array['childcare', 'cooking', 'firstaid']::text[], array['baby', 'toddler']::text[], false, array['tagalog', 'english', 'hiligaynon']::text[], 14500, 'live-in', array['sat']::text[], array['sanjuan']::text[], '2w', 'Nanny at cook para sa pamilyang may tatlong anak. Marunong ako sa baby food at balanced meals para sa mga bata.', 'Hidden-veggie spaghetti the kids ask for.', null, null, null, '[{"text": "Our kids now eat their vegetables, thanks to her.", "who": "Chua family · Greenhills"}]'::jsonb, '[{"years": "2017–2026", "text": "Nanny and cook, Greenhills"}]'::jsonb, 'f', 9, 'Live-in · 1 day off a week', false),
  ('368a020f-15a1-4409-a41d-ef3ca49654d8', 'Nenita', 'O', 49, 'manila', 'ncr', array['allaround']::text[], '{"allaround": 20}'::jsonb, array['cooking', 'laundry', 'childcare']::text[], array[]::text[], false, array['tagalog', 'ilocano']::text[], 12000, 'live-in', array['sun']::text[], array['manila']::text[], '1m', '20 taon na akong kasambahay. Kaya ko ang lahat ng gawaing bahay, at matagal akong nag-alaga ng pamilya.', 'Pancit on everyone’s birthday.', null, null, null, '[{"text": "Sixteen years with our family. She is part of our home.", "who": "Aquino family · Malate"}]'::jsonb, '[{"years": "2010–2026", "text": "All-around kasambahay, Malate"}]'::jsonb, 'f', 20, 'Live-in · Sunday off', false)
insert into public.families (id, family_name, city, region, needs, kids, elder, pets, languages, arrangement, schedule, rest_days, hours, budget_min, budget_max, perks, start_date, about, origin, household_size, helper_notes, house_rule, transport) values
  ('86e32c90-aaf3-4c48-ac8b-261b434b0884', 'Salazar', 'qc', 'ncr', array['nanny']::text[], array[1, 4]::int[], false, array[]::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 11000, 13000, array['ownRoom', 'load']::text[], '2026-12-01', 'Two working parents in Quezon City with a baby and a preschooler. We need a nanny who is patient and loves routines.', 'filipino', 5, '[{"text": "Kind family, and they always paid on time.", "who": "Former nanny · 2 yrs"}]'::jsonb, 'No screens for the kids before 4 PM.', false),
  ('3a58d9f8-bf7b-4d83-a542-ff42bdaaa948', 'Ocampo', 'pasig', 'ncr', array['allaround']::text[], array[8]::int[], false, array['cat']::text[], array['tagalog']::text[], 'live-in', 'full', array['sun']::text[], null, 10000, 12000, array['ownRoom', 'fareHome']::text[], '2026-11-23', 'Mom works in Dubai; dad and our 8-year-old live in Pasig. We need an all-around helper for the home and school days.', 'ofw', 3, '[{"text": "Fair employer and easy to talk to.", "who": "Former helper · 4 yrs"}]'::jsonb, 'Please keep the house quiet during homework time, 4 to 6 PM.', false),
  ('42b23abf-7a61-4c55-ab76-d3c0922dd92f', 'Castillo', 'makati', 'ncr', array['caregiver']::text[], array[]::int[], true, array[]::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 15000, 18000, array['ownRoom', 'hmo']::text[], '2026-12-15', 'We are arranging care for our father, 84, who lives in Makati with our mother. We need a caregiver who is gentle and calm.', 'filipino', 3, '[{"text": "Respectful family who treat you like a relative.", "who": "Former caregiver · 5 yrs"}]'::jsonb, 'Lolo naps from 1 to 3 PM, so we keep things quiet then.', false),
  ('674a418d-8740-4f63-a51e-d3e244c46902', 'Kim', 'bgc', 'ncr', array['housekeeper', 'cook']::text[], array[5, 9]::int[], false, array[]::text[], array['english']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '8:00–17:00', 16000, 19000, array['load', 'hmo']::text[], null, 'Korean–Filipino family in BGC. We need help with cleaning and with cooking simple Filipino and Korean dishes.', 'expat', 4, '[]'::jsonb, 'Shoes off inside, and weekends are always off.', false),
  ('17413608-e5f3-4b5e-a51d-79cdc6c74fe9', 'Morales', 'mandaluyong', 'ncr', array['nanny', 'housekeeper']::text[], array[2, 6]::int[], false, array['dog']::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 12000, 14000, array['ownRoom', 'load']::text[], '2026-12-01', 'Young family in Mandaluyong. We are looking for a nanny who can also help keep the house in order.', 'filipino', 4, '[{"text": "They respected my day off every week.", "who": "Former nanny · 3 yrs"}]'::jsonb, 'We eat dinner together at 7 PM, and you are welcome at the table.', false),
  ('7c324702-5ba3-4618-a370-f87bd9610099', 'Rivera', 'paranaque', 'ncr', array['allaround']::text[], array[3, 7, 12]::int[], false, array[]::text[], array['tagalog']::text[], 'live-in', 'full', array['sun']::text[], null, 11000, 13000, array['ownRoom', 'fareHome']::text[], '2027-01-05', 'Dad works on a ship; mom works full-time in Parañaque. Three kids, a busy house and a lot of laughter.', 'ofw', 5, '[]'::jsonb, 'Tuesdays and Thursdays are market days, and we go together.', false),
  ('71411c30-8e4b-4926-a4fb-65446791e40d', 'Lee', 'makati', 'ncr', array['nanny']::text[], array[4]::int[], false, array[]::text[], array['english']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '9:00–18:00', 15000, 18000, array['load', 'hmo']::text[], '2026-11-30', 'Singaporean family in Salcedo Village with one 4-year-old. We need a nanny who speaks English and enjoys outdoor play.', 'expat', 3, '[]'::jsonb, 'Park time every afternoon, or indoor play when it rains.', true),
  ('c4f87cd0-0b54-4dac-a7d7-dca83709fa05', 'Domingo', 'marikina', 'ncr', array['cook', 'housekeeper']::text[], array[10, 14]::int[], false, array['dog', 'cat']::text[], array['tagalog']::text[], 'live-in', 'full', array['sun']::text[], null, 12000, 14000, array['ownRoom']::text[], '2026-12-08', 'Big family in Marikina, with the grandparents at home. We need someone who enjoys cooking for six.', 'filipino', 6, '[{"text": "Warm family, and the grandmother taught me her recipes.", "who": "Former cook · 6 yrs"}]'::jsonb, 'Grandma''s recipes are welcome; she loves to teach them.', false),
  ('961e64f3-5569-4c45-a795-c60d941fabd1', 'Abellana', 'cebu', 'r7', array['nanny']::text[], array[2, 5]::int[], false, array[]::text[], array['bisaya', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 8500, 10000, array['ownRoom', 'load']::text[], '2026-12-01', 'Taga-Cebu mi. We need a nanny for our two little ones while we run our shop in Mabolo.', 'filipino', 4, '[]'::jsonb, 'We speak Bisaya at home; Tagalog and English are fine too.', false),
  ('2be55489-8b9b-4c51-a584-9d0d04db4c60', 'Sarmiento', 'davao', 'r11', array['housekeeper']::text[], array[]::int[], false, array['dog']::text[], array['bisaya', 'tagalog']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '8:00–16:00', 8000, 9500, array['load']::text[], '2026-11-23', 'Working couple in Matina, Davao. We need help with cleaning, laundry and the dog on weekdays.', 'filipino', 2, '[]'::jsonb, 'Our dog Bruno gets two walks a day.', false),
  ('bd21fcf3-3aee-4a0d-a919-c6983c0d1f6d', 'Hernandez', 'sanjuan', 'ncr', array['nanny', 'housekeeper']::text[], array[1, 3, 6]::int[], false, array[]::text[], array['tagalog', 'english']::text[], 'live-in', 'full', array['sun']::text[], null, 13000, 16000, array['ownRoom', 'hmo', 'load']::text[], '2026-12-01', 'Three kids under seven in Greenhills. We need an extra pair of caring hands, especially for the baby.', 'filipino', 5, '[{"text": "Supportive family; they helped me with my SSS papers.", "who": "Former nanny · 2 yrs"}]'::jsonb, 'The baby sleeps at 7 PM, so we keep the house quiet after that.', false),
  ('34a36f2c-7d3d-4f16-af5c-485d13591ba7', 'Johansson', 'bgc', 'ncr', array['housekeeper']::text[], array[]::int[], false, array['cat']::text[], array['english']::text[], 'live-out', 'full', array['sat', 'sun']::text[], '9:00–15:00', 14000, 16000, array['load']::text[], null, 'Swedish couple in BGC working from home. We need help with cleaning, laundry and plants, three to five days a week.', 'expat', 2, '[]'::jsonb, 'Quiet hours during our calls, 9 to 11 AM.', false)
